content.text:
### Install hk CLI

Source: https://hk.jdx.dev/getting_started

Methods to install the hk tool using various package managers or source compilation.

```shell
mise use hk pkl
hk --version
```

```shell
cargo install hk
```

```shell
brew install hk
```

```shell
aqua g -i jdx/hk
```

--------------------------------

### Initialize hk Project

Source: https://hk.jdx.dev/getting_started

Generates a default hk.pkl configuration file in the root of the current repository.

```shell
hk init
```

--------------------------------

### Basic hk.pkl Configuration Example

Source: https://hk.jdx.dev/configuration.html

This example demonstrates a basic `hk.pkl` file structure. It imports the base configuration, defines custom linters using a mapping, and sets up pre-commit and pre-push hooks. The `amends` directive is crucial for extending the base configuration.

```pkl
amends "package://github.com/jdx/hk/releases/download/v1.38.0/hk@1.38.0#/Config.pkl"
import "package://github.com/jdx/hk/releases/download/v1.38.0/hk@1.38.0#/Builtins.pkl"

local linters = new Mapping<String, Step> {
    // linters can be manually defined
    ["eslint"] {
        // the files to run the linter on, if no files are matched, the linter will be skipped
        // this will filter the staged files and return the subset matching these globs
        glob = List("*.js", "*.ts")
        // the command to run that makes no changes
        check = "eslint {{files}}"
        // the command to run that fixes the files (used by default)
        fix = "eslint --fix {{files}}"
        // optional: files matching these globs will be staged after fix modifies them
        // defaults to the step's glob when staging is enabled, so usually not needed
        // stage = List("*.js", "*.ts")
    }
    // linters can also be specified with the Builtins pkl library
    ["prettier"] = Builtins.prettier
}

hooks {
    ["pre-commit"] {
        fix = true       // runs the fix step to make modifications
        stash = "git"    // stashes unstaged changes before running fix steps
        steps = linters
    }
    ["pre-push"] {
        steps = linters
    }
    // "fix" and "check" are special steps for `hk fix` and `hk check` commands
    ["fix"] {
        fix = true
        steps = linters
    }
    ["check"] {
        steps = linters
        // optional: run a report after the hook finishes; HK_REPORT_JSON contains timing JSON
        report = #"node scripts/upload-timings.js <<<\"$HK_REPORT_JSON\""
    }
}

```

--------------------------------

### Install and Run Hooks

Source: https://hk.jdx.dev/getting_started

Commands to register hooks into the git repository and manually trigger specific hooks.

```shell
hk install
```

```shell
hk run pre-commit
```

### `hk install`

Source: https://hk.jdx.dev/cli/install.html

Sets up git hooks to run hk. The command `hk install` has the usage `hk install [--mise]` and an alias `i`. It configures your project to use Git hooks managed by `hk`.

### Define Custom Linters and Hooks in Pkl

Source: https://github.com/jdx/hk/blob/main/docs/reference/examples/custom-linters.md

Configures custom linters with platform-specific scripts, workspace indicators, and integrated tests, then incorporates them into pre-commit and check hooks.

```pkl
amends "package://github.com/jdx/hk/releases/download/v1.55.0/hk@1.55.0#/Config.pkl"
import "package://github.com/jdx/hk/releases/download/v1.55.0/hk@1.55.0#/Builtins.pkl"

local custom_linters = new Mapping<String, Step> {
  // Custom SQL formatter
  ["sql_formatter"] {
    glob = List("**/*.sql")
    exclude = List("**/migrations/**")
    check = "sql-formatter --check {{files}}"
    fix = "sql-formatter --write {{files}}"
    batch = true
  }

  // Platform-specific security scanner
  ["security_scan"] {
    check = new Script {
      linux = "security-scanner-linux --scan {{files}}"
      macos = "security-scanner-mac --scan {{files}}"
      windows = "security-scanner.exe /scan {{files}}"
    }
    // Only run if security config exists
    condition = "test -f .security-config.yml"
    // Run exclusively to avoid conflicts
    exclusive = true
  }

  // Custom workspace-based build tool
  ["custom_build"] {
    workspace_indicator = "build.toml"
    check = "cd {{workspace}} && custom-build check"
    fix = "cd {{workspace}} && custom-build fix"
    // Use check_diff for efficient patching
    check_diff = "cd {{workspace}} && custom-build diff"
  }

  // Interactive migration tool
  ["migrate"] {
    glob = List("**/migrations/*.sql")
    check = "migrate validate {{files}}"
    fix = "migrate apply {{files}}"
    // Enable interactive mode for prompts
    interactive = true
  }

  // Custom linter with tests
  ["custom_validator"] {
    glob = List("**/*.custom")
    check = "validator {{files}}"
    fix = "validator --fix {{files}}"

    // Define tests for this step
    tests {
      ["validates correct syntax"] {
        run = "check"
        write {
          ["{{tmp}}/test.custom"] = #"valid content"#
        }
        files = List("{{tmp}}/test.custom")
        expect {
          code = 0
        }
      }
      ["fixes invalid syntax"] {
        run = "fix"
        write {
          ["{{tmp}}/broken.custom"] = #"broken  content"#
        }
        files = List("{{tmp}}/broken.custom")
        expect {
          files {
            ["{{tmp}}/broken.custom"] = #"broken content"#
          }
        }
      }
    }
  }
}

// Import some builtins and mix with custom
local all_linters = new Mapping<String, Step> {
  ...custom_linters
  ["prettier"] = Builtins.prettier
  ["shellcheck"] = Builtins.shellcheck
}

hooks {
  ["pre-commit"] {
    fix = true
    stash = "patch-file" // Use patch file instead of git stash
    steps = all_linters
  }
  ["check"] {
    steps = all_linters
    // Generate a report after checking
    report =
      #"""
        echo "Check completed at $(date)"
        echo "Results: $HK_REPORT_JSON" | jq '.'
      ""#
  }
}

// Show additional skip reasons for debugging
display_skip_reasons =
  List(
    "profile-not-enabled",
    "no-files-to-process",
    "condition-false",
  )

// Environment variables for all steps
env {
  ["CUSTOM_VALIDATOR_STRICT"] = "true"
  ["SQL_FORMATTER_CONFIG"] = ".sql-format.yml"
}
```

--------------------------------

### Stash none is a no-op in stash_unstaged

Source: https://github.com/jdx/hk/blob/main/src/git.rs

When stash method is `None`, `stash_unstaged` returns immediately with no git stash push, no index snapshot, and no pop later. The entirety of the stash/merge machinery is skipped.

```rust
    pub fn stash_unstaged(
        &mut self,
        job: &ProgressJob,
        method: StashMethod,
        status: &GitStatus,
    ) -> Result<()> {
        if method == StashMethod::None {
            return Ok(());
        }
        if let Some(repo) = &self.repo
            && repo.head().is_err()
        {
            return Ok(());
```

### Getting Started > hk.pkl

Source: https://github.com/jdx/hk/blob/main/docs/getting_started.md

The hk.pkl file serves as the central configuration for project hooks and linters. It supports manual step definitions, the use of built-in libraries, and the ability to extend existing configurations. Features include file globbing for linter targeting, automatic file fixing, and the ability to stash unstaged changes during execution.

--------------------------------

### Why hk?

Source: https://github.com/jdx/hk/blob/main/docs/why-hk.md

Unlike tools that simply shell out to run linters, hk enables safe parallel execution by managing read/write locks for every file. This prevents race conditions that occur when multiple linters attempt to modify the same file simultaneously.

--------------------------------

### Smart stashing

Source: https://github.com/jdx/hk/blob/main/docs/why-hk.md

hk prevents the common issue where pre-commit hooks accidentally format or lint unstaged work-in-progress code. By stashing only the unstaged changes before running hooks, hk ensures that linters and fixers operate exclusively on the content intended for the commit. This process allows developers to maintain partial commits without risking their unstaged work.

### Execute mise Tasks in hk.pkl

Source: https://hk.jdx.dev/mise_integration.html

Demonstrates how to invoke mise tasks within an hk.pkl configuration file. This allows developers to use mise's task runner features like dependency management and parallel execution within hook steps.

```pkl
amends "package://github.com/jdx/hk/releases/download/v1.38.0/hk@1.38.0#/Config.pkl"

`pre-commit` {
    ["prelint"] {
        check = "mise run prelint"
        exclusive = true
    }
}
```

--------------------------------

### Enable Mise Integration

Source: https://hk.jdx.dev/configuration.html

Enables deep integration with `mise` for tool management. When active, `hk install` uses `mise x` for hook execution, `hk init` creates a `mise.toml` file, and tool discovery automatically uses `mise` shims.

```shell
# Enable mise integration
export HK_MISE=true
```

--------------------------------

### Initialize and Install hk with mise

Source: https://hk.jdx.dev/mise_integration.html

Commands to initialize a project with mise support or install hooks that utilize mise for environment execution. These commands ensure tools are correctly managed and accessible within the hook execution context.

```shell
export HK_MISE=1
hk init --mise
hk install --mise
```

--------------------------------

### Configure Python Development Workflow using Pkl

Source: https://hk.jdx.dev/reference/examples/python-project.html

This snippet defines a mapping of Python linters and formatters, specifying dependencies and execution profiles. It then integrates these tools into git hooks for automated code quality management.

```pkl
amends "package://github.com/jdx/hk/releases/download/v1.38.0/hk@1.38.0#/Config.pkl"
import "package://github.com/jdx/hk/releases/download/v1.38.0/hk@1.38.0#/Builtins.pkl"

local python_linters = new Mapping<String, Step> {
  ["ruff"] = (Builtins.ruff) {
    batch = true
  }
  ["ruff_format"] = (Builtins.ruff_format) {
    depends = "ruff"
  }
  ["black"] = (Builtins.black) {
    depends = "ruff_format"
  }
  ["isort"] = (Builtins.isort) {
    depends = "black"
  }
  ["mypy"] = (Builtins.mypy) {
    stomp = true
    profiles = List("types", "full")
  }
  ["flake8"] = (Builtins.flake8) {
    profiles = List("ci")
  }
}

hooks {
  ["pre-commit"] {
    fix = true
    stash = "git"
    steps = python_linters
  }
  ["pre-push"] {
    steps = python_linters
    env {
      ["HK_PROFILES"] = "types"
    }
  }
  ["check"] {
    steps = python_linters
  }
  ["fix"] {
    fix = true
    steps = python_linters
  }
}

fail_fast = true
```

### mise integration > Task Management

Source: https://hk.jdx.dev/mise_integration.html

Mise tasks can be integrated directly into hk steps, providing access to advanced functionality such as dependency management, option parsing, and parallel execution. You can invoke mise commands within your `hk.pkl` configuration just like any other command. This allows you to offload complex task logic to mise while maintaining the hook-triggering capabilities of hk.

=== hooks claude-code ===
{
  "hooks": {
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "hk run check --safe --format json"
          }
        ]
      }
    ]
  }
}
=== hooks codex ===
{
  "hooks": {
    "Stop": [
      {
        "matcher": null,
        "hooks": [
          {
            "type": "command",
            "command": "hk run check --safe --format json",
            "timeout": 120
          }
        ]
      }
    ]
  }
}
=== hooks vscode ===
{
  "version": "2.0.0",
  "tasks": [
    {
      "label": "hk: safe check",
      "type": "shell",
      "command": "hk run check --safe --format json",
      "problemMatcher": []
    }
  ]
}
=== mcp vscode ===
{
  "servers": {
    "hk": {
      "type": "stdio",
      "command": "hk",
      "args": ["mcp", "--root", "."]
    }
  }
}
=== mcp claude-code ===
claude mcp add --transport stdio hk -- hk mcp --root .

