+    tail_cur_width += cp_width;
+    i = prev_i;
+    tail_start_offset = i;
+  }
+
+  std::string result;
+  result.reserve(head_byte_len + ellipsis.size() + (text.size() - tail_start_offset));
+  result.append(text.substr(0, head_byte_len));
+  result.append(ellipsis);
+  result.append(text.substr(tail_start_offset));
+  return result;
+}
+
