### Define Step Tests with Lifecycle Hooks

Source: https://hk.jdx.dev/configuration.html

Shows how to define self-contained tests for steps, including setup via 'write' or 'before' hooks, execution modes, and validation using 'expect' and 'after' hooks.

```pkl
hooks {
  ["check"] {
    steps {
      ["prettier"] {
        check = "prettier --check {{ files }}"
        fix = "prettier --write {{ files }}"
        tests {
          ["formats json via fix"] {
            run = "fix"
            write { ["{{tmp}}/a.json"] = "{\"b\":1}" }
            expect { files { ["{{tmp}}/a.json"] = "{\n  \"b\": 1\n}\n" } }
          }
          ["check shows output"] {
            run = "check"
            files = List("{{tmp}}/a.json")
            env { ["FOO"] = "bar" }
            expect { stdout = "prettier" }
          }
          ["before generates file, after verifies contents"] {
            run = "fix"
            before = #"printf '{"b":1}' > {{tmp}}/raw.json"#
            files = List("{{tmp}}/raw.json")
            after = #"grep -q '"b": 1' {{tmp}}/raw.json"#
            expect { files { ["{{tmp}}/raw.json"] = "{\n  \"b\": 1\n}\n" } }
          }
        }
      }
    }
  }
}
```

--------------------------------

### Define Custom Linters and Hooks in Pkl

Source: https://hk.jdx.dev/reference/examples/custom-linters.html

Demonstrates how to define custom linting steps including SQL formatters, platform-specific security scanners, and workspace-aware build tools. It also shows how to integrate these custom steps with built-in linters and configure pre-commit hooks.

```pkl
amends "package://github.com/jdx/hk/releases/download/v1.38.0/hk@1.38.0#/Config.pkl"
import "package://github.com/jdx/hk/releases/download/v1.38.0/hk@1.38.0#/Builtins.pkl"

local custom_linters = new Mapping<String, Step> {
  ["sql_formatter"] {
    glob = List("**/*.sql")
    exclude = List("**/migrations/**")
    check = "sql-formatter --check {{files}}"
    fix = "sql-formatter --write {{files}}"
    batch = true
  }

  ["security_scan"] {
    check = new Script {
      linux = "security-scanner-linux --scan {{files}}"
      macos = "security-scanner-mac --scan {{files}}"
      windows = "security-scanner.exe /scan {{files}}"
    }
    condition = "test -f .security-config.yml"
    exclusive = true
  }

  ["custom_build"] {
    workspace_indicator = "build.toml"
    check = "cd {{workspace}} && custom-build check"
    fix = "cd {{workspace}} && custom-build fix"
    check_diff = "cd {{workspace}} && custom-build diff"
  }

  ["migrate"] {
    glob = List("**/migrations/*.sql")
    check = "migrate validate {{files}}"
    fix = "migrate apply {{files}}"
    interactive = true
  }

  ["custom_validator"] {
    glob = List("**/*.custom")
    check = "validator {{files}}"
    fix = "validator --fix {{files}}"

    tests {
      ["validates correct syntax"] {
        run = "check"
        write {
          ["{{tmp}}/test.custom"] = #"valid content"#
        }
        files = List("{{tmp}}/test.custom")
        expect {
          code = 0
        }
      }
    }
  }
}

hooks {
  ["pre-commit"] {
    fix = true
    stash = "patch-file"
    steps = custom_linters
  }
}
```

--------------------------------

### Define Check Command for Steps

Source: https://hk.jdx.dev/configuration.html

Specifies a command to run for checking files without modifying them. This command should return a non-zero exit code if errors are found. Examples show a simple string command and a `Script` object for OS-specific commands.

```pkl
hooks {
    ["pre-commit"] {
        ["prettier"] {
            check = "prettier --check {{files}}"
        }
    }
}

If you want to use a different check command for different operating systems, you can define a Script instead of a String:
pkl
hooks {
    ["pre-commit"] {
        ["prettier"] {
            check = new Script {
                linux = "prettier --check {{files}}"
                macos = "prettier --check {{files}}"
                windows = "prettier --check {{files}}"
                other = "prettier --check {{files}}"
            }
        }
    }
}
```

--------------------------------

### Configure Step Exclusivity

Source: https://hk.jdx.dev/configuration.html

When set to true, the step waits for all previous steps to finish before starting, effectively isolating the execution.

```pkl
hooks {
    ["pre-commit"] {
        steps {
            ["prelint"] {
                exclusive = true
                check = "mise run prelint"
            }
            ["postlint"] {
                exclusive = true
                check = "mise run postlint"
            }
        }
    }
}
```

--------------------------------

### Configure Conditional Execution

Source: https://hk.jdx.dev/configuration.html

Controls whether a step runs based on a condition evaluated per job (condition) or once for the whole step (step_condition).

```pkl
local linters = new Mapping<String, Step> {
    ["prettier"] {
        condition = "exec('test -f check.js')"
    }
}
```

