+  TestJsonRoundTrip();
+  TestInvalidSelectionNormalization();
+  TestValidation();
+  TestResolverSelectionAndFallback();
+  TestSceneMenuShortcutConfig();
+  TestSceneMenuShortcutPrecedence();
+  return 0;
+}
