void ResourcePage::abortDownload() {
  if (downloadWorker_ && downloadWorker_->isRunning()) {
    downloadWorker_->disconnect();
    downloadWorker_->quit();
    downloadWorker_->wait();
    delete downloadWorker_;
    downloadWorker_ = nullptr;
  }
}

