### Nix (flake)

Supports `x86_64-linux` and `aarch64-linux`. Binary cache is available via [Cachix](https://fcitx5-vinput.cachix.org) — pre-built binaries are used automatically when building the flake.

#### Home Manager example

Add `fcitx5-vinput` as a flake input:

```nix
{
  description = "Your flake description";

  inputs = {
    nixpkgs.url = "github:nixos/nixpkgs?ref=nixos-unstable";
    home-manager.url = "github:nix-community/home-manager";
    home-manager.inputs.nixpkgs.follows = "nixpkgs";

    fcitx5-vinput = {
      url = "github:xifan2333/fcitx5-vinput";
    };
  };

  # Trust the fcitx5-vinput binary cache so nix uses pre-built binaries
  nixConfig = {
    extra-substituters = [ "https://fcitx5-vinput.cachix.org" ];
    extra-trusted-public-keys = [ "fcitx5-vinput.cachix.org-1:XpX3AA6+dDIX4qJhb1QM7sbTwX6/qSlGvW8Z5NK6XdU=" ];
  };

  outputs =
    {
      self,
      nixpkgs,
      nixos-hardware,
      home-manager,
      ...
    }@inputs:
    let
      system = "x86_64-linux";
      pkgs = import nixpkgs {
        inherit system;
      };
      homeManagerConfiguration = home-manager.lib.homeManagerConfiguration;
    in
    {
      homeConfigurations = {
        "kakapt@krypton" = homeManagerConfiguration {
          inherit pkgs;
          modules = [ ./your_home_module.nix ];
          extraSpecialArgs = inputs;
        };
      };
    };
}
```

